INSERT INTO elements (id,name,icon,category,subcategory,difficulty,difficulty_label,reps,muscles,image,video,video_search,description,requirements,steps,tips,demo_available) VALUES (1,'Универсальная стойка','','Стойка','Универсальная стойка','easy','Лёгкий','техника × 6–10',ARRAY['Ноги','Корпус','Хват']::text[],'/wrestling-japan.png',NULL,'Universal wrestling stance wrestling tutorial','Нейтральная разножка для перемещений, защиты и атак в большинстве борцовских дисциплин.','[]', ARRAY['Стопы примерно на ширине плеч, одна нога чуть впереди, колени мягкие, таз под контролем, корпус слегка собран. Голова выше плеч, руки готовы закрывать линию атаки. Двигайся короткими шагами, не скрещивая ноги.']::text[],'Отрабатывай технику постепенно; сложные броски, болевые и удушающие — только с тренером и на подходящем покрытии.',FALSE);
INSERT INTO elements (id,name,icon,category,subcategory,difficulty,difficulty_label,reps,muscles,image,video,video_search,description,requirements,steps,tips,demo_available) VALUES (2,'Перемещение вперёд','','Стойка','Универсальная стойка','easy','Лёгкий','техника × 6–10',ARRAY['Ноги','Корпус','Хват']::text[],'/wrestling-japan.png',NULL,'Wrestling stance forward step wrestling tutorial','Короткое движение всей стойкой без потери баланса.','[]', ARRAY['Сначала двигается ближняя к направлению нога, вторая догоняет. Не выпрямляй колени и не своди стопы.']::text[],'Отрабатывай технику постепенно; сложные броски, болевые и удушающие — только с тренером и на подходящем покрытии.',FALSE);
INSERT INTO elements (id,name,icon,category,subcategory,difficulty,difficulty_label,reps,muscles,image,video,video_search,description,requirements,steps,tips,demo_available) VALUES (3,'Перемещение назад','','Стойка','Универсальная стойка','easy','Лёгкий','техника × 6–10',ARRAY['Ноги','Корпус','Хват']::text[],'/wrestling-japan.png',NULL,'Wrestling stance back step wrestling tutorial','Отход с сохранением дистанции и готовности к контратаке.','[]', ARRAY['Не откидывай корпус назад. Уходи тазом и стопами, сохраняя плечи над опорой.']::text[],'Отрабатывай технику постепенно; сложные броски, болевые и удушающие — только с тренером и на подходящем покрытии.',FALSE);
