INSERT INTO base_blocks(title,content,items,sort_order) VALUES ('Универсальная стойка','Общий фундамент для перемещений и технической работы.',ARRAY['Разножка','Мягкие колени','Центр тяжести под контролем','Не скрещивать ноги']::text[],1);
INSERT INTO base_blocks(title,content,items,sort_order) VALUES ('Домашняя подготовка','Три этапа: база, связки, раунды.',ARRAY['Разминка','Техника','Резина','Сила','Корпус','Восстановление']::text[],2);
INSERT INTO base_blocks(title,content,items,sort_order) VALUES ('Прогресс','Сначала качество, затем объём, сопротивление и сложность.',ARRAY['Один параметр за раз','Шаг 5–10%','Разгрузка каждые 3–4 тяжёлые недели']::text[],3);
INSERT INTO safety_items(id,name,icon,category,image,description,benefits,tips) VALUES (1,'Укэми','','Безопасность','/wrestling-japan.png','Освой падения и перекаты до амплитудных бросков.',ARRAY['Мягкое покрытие','Контроль головы','Тренер для сложных элементов']::text[],'Не отрабатывай амплитудные падения на твёрдом полу.');
INSERT INTO safety_items(id,name,icon,category,image,description,benefits,tips) VALUES (2,'Партнёрская работа','','Спарринг','/wrestling-japan.png','Сложные броски, болевые и удушающие требуют подготовленного партнёра.',ARRAY['Стоп-сигнал','Контроль силы','Постепенность']::text[],'Сигнал партнёра означает немедленную остановку.');
INSERT INTO safety_items(id,name,icon,category,image,description,benefits,tips) VALUES (3,'Оборудование','','Дом','/wrestling-japan.png','Проверь мат, резину, турник и брусья перед тренировкой.',ARRAY['Нет люфта','Нет повреждений','Свободная зона']::text[],'При повреждении оборудование не использовать.');
INSERT INTO safety_items(id,name,icon,category,image,description,benefits,tips) VALUES (4,'Самочувствие','','Восстановление','/wrestling-japan.png','Не начинай интенсивную работу при острой боли, головокружении или плохом самочувствии.',ARRAY['Сон','Гидратация','Разминка']::text[],'При необычной боли прекращай упражнение и обратись к специалисту.');
